import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { Fretboard3D, type NeckState } from './fretboard3d';
import type { ApkGuitar3D } from './apkGuitar3d';
import { getGuitarLook, type GuitarLook } from './guitarLook';
import { DEFAULT_STAGE_VIEW, type StageFamily, type StageModelStatus, type StageStep, type StageView } from './stageViews';

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const smooth = (value: number) => { const t = clamp01(value); return t * t * (3 - 2 * t); };
export const fretsKey = (frets: readonly (number | null)[]) => frets.map(fret => fret === null ? 'x' : String(fret)).join('.');

interface ViewPreset { target: THREE.Vector3; dir: THREE.Vector3; up: THREE.Vector3; distance: number; halfW: number; halfH: number }
const vec = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const ROLL_UP = vec(-0.3, 0, 0.95).normalize();
const FRETBOARD_HOME = vec(0.7, 10.8, 9.3);

function viewPreset(view: Exclude<StageView, 'split'>, chordX: number): ViewPreset {
  switch (view) {
    case 'fretboard': return { target: vec(0, 0, 0), dir: FRETBOARD_HOME.clone().normalize(), up: vec(0, 1, 0), distance: FRETBOARD_HOME.length(), halfW: 8.4, halfH: 2.6 };
    case 'player': return { target: vec(5, 0, 0.2), dir: vec(0.2, 0.45, 0.87).normalize(), up: vec(0, 1, 0), distance: 26, halfW: 12.8, halfH: 5.2 };
    case 'guitar': return { target: vec(6.5, -1, 0), dir: vec(0.3, 0.84, 0.45).normalize(), up: ROLL_UP, distance: 50, halfW: 22.5, halfH: 12 };
    case 'fretting': return { target: vec(chordX, 0.2, -0.45), dir: vec(-0.22, 0.9, 0.38).normalize(), up: ROLL_UP, distance: 15, halfW: 4.6, halfH: 3.7 };
    case 'strumming': return { target: vec(13.6, 0.5, 0.4), dir: vec(0.18, 0.88, 0.44).normalize(), up: ROLL_UP, distance: 16, halfW: 5.4, halfH: 4.4 };
    default: return { target: vec(6.2, 0, 1.2), dir: vec(0, 1, 0.14).normalize(), up: ROLL_UP, distance: 46, halfW: 20, halfH: 10 };
  }
}

const MAX_FOV = 50;
function fitCamera(camera: THREE.PerspectiveCamera, preset: ViewPreset, mirror: number): void {
  const need = Math.max(preset.halfH, preset.halfW / Math.max(camera.aspect, 0.01));
  let distance = preset.distance;
  let fov = THREE.MathUtils.radToDeg(2 * Math.atan(need / distance));
  if (fov > MAX_FOV) { fov = MAX_FOV; distance = need / Math.tan(THREE.MathUtils.degToRad(MAX_FOV / 2)); }
  camera.fov = fov;
  camera.up.set(preset.up.x * mirror, preset.up.y, preset.up.z);
  const target = vec(preset.target.x * mirror, preset.target.y, preset.target.z);
  camera.position.set(preset.dir.x * mirror, preset.dir.y, preset.dir.z).multiplyScalar(distance).add(target);
  camera.lookAt(target);
  camera.updateProjectionMatrix();
}

export type HandStatus = 'loading' | 'ready' | 'failed';
type Frets = readonly (number | null)[];
interface SplitPane { camera: THREE.PerspectiveCamera; view: 'fretting' | 'strumming'; x: number; y: number; w: number; h: number }
const FOCUS = new THREE.Vector3(), SIZE = new THREE.Vector2();

/** The native acoustic player shares the base neck's picking, accessibility and on-demand lifecycle. */
export class GuitarStage3D extends Fretboard3D {
  // The base constructor calls buildScene; initialisers here would overwrite its state afterward.
  declare onHandStatus: ((status: HandStatus) => void) | null;
  declare onModelStatus: ((status: StageModelStatus) => void) | null;
  private declare look: GuitarLook;
  private declare view: StageView;
  private declare userMoved: boolean;
  private declare zoomScale: number;
  private declare focus: THREE.Vector3;
  private declare splitCamera: THREE.PerspectiveCamera;
  private declare chordX: number;
  private declare cameraTween: { start: number; from: number; to: number } | null;
  private declare clock: () => number;
  private declare reducedMotion: MediaQueryList;
  private declare envTarget: THREE.WebGLRenderTarget | null;
  private declare apk: ApkGuitar3D | null;
  private declare apkStatus: StageModelStatus['state'];
  private declare apkError: string;
  private declare modelStatusKey: string;
  private declare neckState: NeckState | null;
  private declare handsEnabled: boolean;
  private declare idleFrets: Frets;
  private declare family: StageFamily;
  private declare playingUntil: number;
  private declare shapeQueue: Frets[];
  private declare shapeTimer: number;

  constructor(host: HTMLElement, onPick: (string: number, fret: number) => void, onUnavailable: () => void, descriptionId?: string) {
    super(host, onPick, onUnavailable, descriptionId);
    this.renderer.domElement.setAttribute('aria-label',
      'Interactive acoustic guitar with animated hands. Drag to orbit; click a string on the neck to hear it. Use the 2D view for keyboard-accessible frets.');
  }

  protected buildScene(): void {
    this.initState();
    this.buildLighting();
    this.buildTargets(12);
    this.applyView();
    this.retryScene();
  }

  private initState(): void {
    this.onHandStatus = this.onModelStatus = null;
    this.look = getGuitarLook();
    this.view = DEFAULT_STAGE_VIEW;
    this.userMoved = false;
    this.zoomScale = 1;
    this.focus = new THREE.Vector3();
    this.splitCamera = new THREE.PerspectiveCamera(38, 1, 0.5, 300);
    this.chordX = -3.5;
    this.cameraTween = null;
    this.clock = () => performance.now() / 1000;
    this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
    this.envTarget = null;
    this.apk = null;
    this.apkStatus = 'idle';
    this.apkError = '';
    this.modelStatusKey = '';
    this.neckState = null;
    this.handsEnabled = true;
    this.idleFrets = [null, null, null, null, null, null];
    this.family = 'strum';
    this.playingUntil = 0;
    this.shapeQueue = [];
    this.shapeTimer = 0;
    this.camera.near = 0.5;
    this.camera.far = 300;
  }

  private buildLighting(): void {
    for (const child of [...this.world.children]) if (child instanceof THREE.Light) this.world.remove(child);
    const { renderer } = this;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFShadowMap;
    renderer.toneMapping = THREE.NeutralToneMapping;
    renderer.toneMappingExposure = 1;
    const generator = new THREE.PMREMGenerator(renderer), room = new RoomEnvironment();
    this.envTarget = generator.fromScene(room, 0.04);
    room.dispose(); generator.dispose();
    this.scene.environment = this.envTarget.texture;
    this.scene.environmentIntensity = 0.65;
    this.world.add(new THREE.HemisphereLight(0xfff2e7, 0x232c27, 0.65));
    const key = new THREE.DirectionalLight(0xfff4e9, 2.5);
    key.position.set(-6, 22, 10); key.target.position.set(6, 0, 0);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    Object.assign(key.shadow.camera, { left: -22, right: 22, top: 22, bottom: -22, near: 1, far: 70 });
    key.shadow.camera.updateProjectionMatrix();
    key.shadow.radius = 4; key.shadow.normalBias = 0.035; key.shadow.bias = -0.0004;
    const rim = new THREE.DirectionalLight(0xcfe2f5, 1.3); rim.position.set(14, 8, -14);
    const fill = new THREE.DirectionalLight(0xffe9d2, 0.45); fill.position.set(8, 7, 12);
    this.world.add(key, key.target, rim, fill);
  }

  retryScene(): void {
    if (this.disposed || this.apk || this.apkStatus === 'loading') return;
    this.apkStatus = 'loading'; this.apkError = '';
    this.publishModelStatus();
    void import('./apkGuitar3d').then(module => module.loadApkGuitar()).then(apk => {
      if (this.disposed) { apk.dispose(); return; }
      try {
        apk.setSkin(this.look.skin);
        apk.follow(this.idleFrets, this.family, performance.now() / 1000);
      } catch (error) { apk.dispose(); throw error; }
      this.apk = apk;
      this.apkStatus = 'ready';
      this.world.add(apk.root);
      this.refreshScene();
      this.pumpShapes();
    }).catch(error => {
      if (this.disposed) return;
      this.apk?.dispose(); this.apk = null;
      this.apkStatus = 'failed';
      this.apkError = error instanceof Error ? error.message : String(error);
      console.warn('Original acoustic scene unavailable. Retry or use the 2D player.', error);
      this.publishModelStatus();
      this.syncHands();
    });
  }

  getHandStatus(): HandStatus { return this.apkStatus === 'ready' ? 'ready' : this.apkStatus === 'failed' ? 'failed' : 'loading'; }

  getModelStatus(): StageModelStatus {
    const preview = this.apk?.preview ?? null;
    const message = this.apkStatus === 'failed' ? `Original acoustic could not load (${this.apkError}). Retry or switch to 2D.`
      : this.apkStatus !== 'ready' ? 'Loading the acoustic guitar and its hands...'
      : preview ? `Original ${this.apk!.choices.find(clip => clip.name === preview)!.label} preview. Motion only; your progression is unchanged.`
      : 'Original acoustic guitar. Hands follow your selected shape; playback uses the original motions.';
    return { model: 'apk', state: this.apkStatus, message, clips: this.apk?.choices ?? [], preview };
  }

  private publishModelStatus(): void {
    const status = this.getModelStatus(), key = `${status.state}:${status.message}`;
    if (key === this.modelStatusKey) return;
    this.modelStatusKey = key;
    this.onHandStatus?.(this.getHandStatus());
    this.onModelStatus?.(status);
  }

  setHandsVisible(visible: boolean): void { this.handsEnabled = visible; this.syncHands(); }

  private syncHands(render = true): void {
    const show = this.handsEnabled && this.view !== 'fretboard';
    this.apk?.setHandsVisible(show);
    this.markers.visible = Boolean(this.apk) && !this.apk?.preview && !show;
    if (render) this.requestRender();
  }

  private refreshScene(): void {
    const apk = this.apk!;
    for (const target of this.targets) {
      const s = target.userData.string as number, f = target.userData.fret as number, x = this.noteX(f);
      const point = apk.stringPoint(s, x);
      target.position.set(x, point.y + .09, point.z);
      const width = f ? this.fretX(f) - this.fretX(f - 1) : .7;
      const originalWidth = f ? super.fretX(f) - super.fretX(f - 1) : .7;
      const spacing = Math.abs(apk.stringPoint(Math.min(5, s + 1), x).z - apk.stringPoint(Math.max(0, s - 1), x).z) / (s === 0 || s === 5 ? 1 : 2);
      target.scale.set(width / originalWidth, 1, spacing / .39);
    }
    if (this.neckState) this.updateMarkers(this.neckState);
    this.chordX = this.shapeCentre(this.idleFrets);
    this.cameraTween = null;
    this.applyView();
    this.publishModelStatus();
  }

  previewOriginalClip(name: string): void {
    if (!this.apk) throw new Error('Wait for the acoustic scene before previewing an animation');
    this.apk.previewClip(name, performance.now() / 1000);
    if (this.apk.frettingFrets) this.chordX = this.shapeCentre(this.apk.frettingFrets);
    this.cameraTween = null;
    this.fitView();
    this.publishModelStatus();
    this.syncHands();
  }

  followProgression(): void {
    this.apk?.follow(this.idleFrets, this.family, performance.now() / 1000);
    this.chordX = this.shapeCentre(this.idleFrets);
    this.cameraTween = null;
    this.fitView();
    this.publishModelStatus();
    this.syncHands();
  }

  protected fretX(fret: number): number {
    if (!this.apk) return super.fretX(fret);
    const frets = this.apk.info.layout.frets;
    const index = Math.min(frets.length - 1, Math.max(0, Math.floor(fret)));
    return frets[index] + (fret - index) * ((frets[index + 1] ?? frets[index]) - frets[index]);
  }

  private shapeCentre(frets: Frets): number {
    const pressed = frets.filter((fret): fret is number => fret !== null && fret > 0);
    return pressed.length ? pressed.reduce((sum, fret) => sum + this.noteX(fret), 0) / pressed.length : this.noteX(2);
  }

  private updateMarkers(state: NeckState): void {
    super.update(state);
    if (this.apk) for (const marker of this.markers.children) {
      const s = Math.max(0, Math.min(5, Math.round(marker.position.z / .4 + 2.5)));
      const point = this.apk.stringPoint(s, marker.position.x);
      marker.position.z = point.z;
      marker.position.y += point.y - .212;
      marker.scale.multiplyScalar(.7);
    }
    this.syncHands(false);
  }

  /** Warm one selected shape per task, away from the audio scheduling callback. */
  prepareShapes(shapes: readonly Frets[]): void {
    this.shapeQueue = [...new Map(shapes.map(frets => [fretsKey(frets), [...frets]])).values()];
    this.pumpShapes();
  }

  private pumpShapes(): void {
    if (this.shapeTimer || this.disposed || !this.apk || !this.shapeQueue.length) return;
    this.shapeTimer = window.setTimeout(() => {
      this.shapeTimer = 0;
      const next = this.shapeQueue.shift();
      if (next && !this.disposed) {
        try { this.apk?.prepare(next); }
        catch (error) {
          console.warn('The selected hand shape could not be prepared.', error);
          this.apkError = error instanceof Error ? error.message : String(error);
          this.apkStatus = 'failed';
          this.apk?.dispose(); this.apk = null;
          this.publishModelStatus(); this.syncHands();
          return;
        }
      }
      this.pumpShapes();
    }, 0);
  }

  protected applyLook(look: GuitarLook): void {
    const mirrorChanged = (look.hand === 'left' ? -1 : 1) !== this.mirror;
    super.applyLook(look);
    this.look = look;
    this.apk?.setSkin(look.skin);
    if (mirrorChanged) this.applyView();
    this.requestRender();
  }

  setView(view: StageView): void { this.view = view; this.userMoved = false; this.zoomScale = 1; this.applyView(); }
  getView(): StageView { return this.view; }

  private applyView(): void {
    this.fitView();
    this.controls.dispose();
    const controls = new OrbitControls(this.camera, this.renderer.domElement);
    controls.enablePan = controls.enableZoom = controls.enableDamping = false;
    controls.minPolarAngle = 0.05; controls.maxPolarAngle = Math.PI - 0.05;
    controls.enabled = this.view !== 'split';
    controls.target.copy(this.focus);
    let dragging = false;
    controls.addEventListener('start', () => { dragging = true; });
    controls.addEventListener('end', () => { dragging = false; });
    controls.addEventListener('change', () => { if (dragging) this.userMoved = true; this.requestRender(); });
    controls.update();
    this.controls = controls;
    this.syncHands();
  }

  private placeCamera(camera: THREE.PerspectiveCamera, preset: ViewPreset): void {
    fitCamera(camera, preset, this.mirror);
    const target = FOCUS.set(preset.target.x * this.mirror, preset.target.y, preset.target.z);
    if (this.zoomScale !== 1) camera.position.sub(target).multiplyScalar(this.zoomScale).add(target);
    if (camera === this.camera) this.focus.copy(target);
  }

  private splitPanes(width: number, height: number): SplitPane[] {
    const gap = 3;
    if (width / height < 1.1) {
      const h = (height - gap) / 2;
      return [
        { camera: this.camera, view: 'fretting', x: 0, y: h + gap, w: width, h },
        { camera: this.splitCamera, view: 'strumming', x: 0, y: 0, w: width, h },
      ];
    }
    const w = (width - gap) / 2, neckLeft = this.mirror === 1;
    return [
      { camera: this.camera, view: 'fretting', x: neckLeft ? 0 : w + gap, y: 0, w, h: height },
      { camera: this.splitCamera, view: 'strumming', x: neckLeft ? w + gap : 0, y: 0, w, h: height },
    ];
  }

  private fitView(): void {
    const { x: width, y: height } = this.renderer.getSize(SIZE);
    if (!width || !height) return;
    if (this.view === 'split') {
      for (const pane of this.splitPanes(width, height)) {
        pane.camera.aspect = pane.w / Math.max(1, pane.h);
        this.placeCamera(pane.camera, viewPreset(pane.view, this.chordX));
      }
    } else {
      this.camera.aspect = width / height;
      const preset = viewPreset(this.view, this.chordX);
      if (this.userMoved) {
        const need = Math.max(preset.halfH, preset.halfW / this.camera.aspect);
        this.camera.fov = Math.min(MAX_FOV, THREE.MathUtils.radToDeg(2 * Math.atan(need / preset.distance)));
        this.camera.updateProjectionMatrix();
        return;
      }
      this.placeCamera(this.camera, preset);
    }
    this.controls.target.copy(this.focus);
  }

  protected resize(): void {
    const { width, height } = this.host.getBoundingClientRect();
    if (!width || !height || this.disposed) return;
    this.renderer.setSize(width, height, false); this.fitView(); this.requestRender();
  }

  zoom(factor: number): void {
    const next = THREE.MathUtils.clamp(this.zoomScale * factor, 0.35, 2.5);
    if (next === this.zoomScale) return;
    const ratio = next / this.zoomScale; this.zoomScale = next;
    if (this.userMoved && this.view !== 'split') {
      this.camera.position.sub(this.controls.target).multiplyScalar(ratio).add(this.controls.target);
      this.controls.update();
    } else this.fitView();
    this.requestRender();
  }

  reset(): void { this.userMoved = false; this.zoomScale = 1; this.fitView(); this.controls.update(); this.requestRender(); }

  protected setPickRay(clientX: number, clientY: number): boolean {
    if (!this.apk || this.apk.preview) return false;
    if (this.view !== 'split') return super.setPickRay(clientX, clientY);
    const rect = this.renderer.domElement.getBoundingClientRect();
    if (!rect.width || !rect.height) return false;
    const x = clientX - rect.left, y = rect.height - (clientY - rect.top);
    const pane = this.splitPanes(rect.width, rect.height).find(p => x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h);
    if (!pane) return false;
    this.raycaster.setFromCamera(new THREE.Vector2((x - pane.x) / pane.w * 2 - 1, (y - pane.y) / pane.h * 2 - 1), pane.camera);
    return true;
  }

  setClock(clock: () => number): void { this.clock = clock; }

  update(state: NeckState): void {
    const changed = fretsKey(state.frets) !== fretsKey(this.idleFrets);
    this.neckState = state; this.updateMarkers(state); this.idleFrets = [...state.frets];
    const now = performance.now() / 1000;
    if (now >= this.playingUntil && (!this.apk?.preview || changed)) this.scheduleFrets(this.idleFrets, now + .25, .3, now);
  }

  playStep(step: StageStep, next: StageStep | null): void {
    if (this.disposed) return;
    const now = performance.now() / 1000, offset = now - this.clock(), at = step.at + offset;
    this.playingUntil = at + step.stepSeconds + .6;
    this.setFamily(step.family);
    if (step.frets) this.scheduleFrets(step.frets, at, step.stepSeconds, now);
    if (next?.frets) this.scheduleFrets(next.frets, next.at + offset, next.stepSeconds, now);
    this.apk?.playStep(step, at, this.reducedMotion.matches);
    this.publishModelStatus(); this.requestRender();
  }

  stopPlayback(): void {
    this.playingUntil = 0;
    this.followProgression();
  }

  setFamily(family: StageFamily): void {
    if (family === this.family) return;
    this.family = family; this.apk?.setFamily(family); this.requestRender();
  }

  private scheduleFrets(frets: Frets, at: number, stepSeconds: number, now: number): void {
    this.apk?.scheduleFrets(frets, at, stepSeconds, now);
    const x = this.shapeCentre(frets);
    if (Math.abs(x - (this.cameraTween?.to ?? this.chordX)) > .05) this.cameraTween = { start: Math.max(now, at - .2), from: this.chordX, to: x };
    this.requestRender();
  }

  private animate(now: number): boolean {
    let active = this.apk?.update(now, this.reducedMotion.matches) ?? false;
    if (this.cameraTween) {
      const tween = this.cameraTween, p = this.reducedMotion.matches ? 1 : clamp01((now - tween.start) / .4);
      this.chordX = tween.from + (tween.to - tween.from) * smooth(p);
      if (p >= 1) this.cameraTween = null; else active = true;
      if (this.view === 'split' || (this.view === 'fretting' && !this.userMoved)) this.fitView();
    }
    this.syncHands(false); this.publishModelStatus();
    return active;
  }

  protected renderFrame(time: number): void {
    const active = this.animate(time / 1000), { renderer } = this;
    renderer.shadowMap.autoUpdate = false; renderer.shadowMap.needsUpdate = true;
    if (this.view === 'split') {
      const { x: width, y: height } = renderer.getSize(SIZE);
      renderer.setScissorTest(false); renderer.setViewport(0, 0, width, height); renderer.clear();
      renderer.setScissorTest(true);
      for (const pane of this.splitPanes(width, height)) {
        renderer.setViewport(pane.x, pane.y, pane.w, pane.h);
        renderer.setScissor(pane.x, pane.y, pane.w, pane.h);
        renderer.render(this.scene, pane.camera);
      }
      renderer.setScissorTest(false); renderer.setViewport(0, 0, width, height);
    } else renderer.render(this.scene, this.camera);
    if (active) this.requestRender();
  }

  dispose(): void {
    if (this.disposed) return;
    clearTimeout(this.shapeTimer);
    this.apk?.dispose(); this.apk = null;
    this.envTarget?.dispose(); this.envTarget = null;
    super.dispose();
  }
}
